import{z as n,x as c,o as r,c as p,q as i,j as E,D as s,d as t,s as d,S as l,b as a}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"接收路径","description":"","frontmatter":{"title":"接收路径","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/rx-path.md","filePath":"cs/rx-path.md","lastUpdated":1791413859000}'),A={name:"cs/rx-path.md"};function B(_,e,P,f,u,m){const o=c("Mermaid");return r(),p("div",null,[e[2]||(e[2]=i('<h1 id="接收路径" tabindex="-1">接收路径 <a class="header-anchor" href="#接收路径" aria-label="Permalink to &quot;接收路径&quot;">​</a></h1><div class="epigraph"><p>一帧从 NAPI 进入协议钩子：以太网 → IP → L4，再由套接字查找把 sk_buff 挂进接收队列，唤醒读者。</p><footer>—— 据 Benvenuti, <em>ULNI</em>；Linux 对 netif_receive_skb 之后路径的文档</footer></div><p><a href="/cs/gro-gso">GRO</a> 把 skb 交给 <code>netif_receive_skb</code>。缺口是 <strong>整条 RX</strong>：ptype 分发、iptables 前半、路由、TCP 输入、直到 <code>sk_data_ready</code>。本课串路径，不把 TCP 拥塞算法写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>驱动不知哪个进程要这包。内核：根据以太网类型找 <code>packet_type</code>，IP 查 fib，再 <code>tcp_v4_rcv</code> 用四元组找 <code>sock</code>。无套接字则 drop 或 ICMP。缺口：early demux、RPS/RFS 把包steer到 CPU；<a href="/cs/netfilter-conntrack">netfilter</a> 钩子插在 PREROUTING/INPUT；用户未 <code>read</code> 则队列有上限，超则丢——背压后课。本课不把 XDP 的先发制人展开，只承认它可在 NAPI 更早 drop/redirect。</p><p><span class="marginnote">busy poll 时用户线程可能自己把包从队列取走。抓包 AF_PACKET 在 ptype 上再挂一个处理者。</span></p><p><span class="marginnote">「四元组」就是（源 IP、源端口、目的 IP、目的端口）这四个数拼成的一把钥匙——同一台机器上几万个 TCP 连接，全靠它区分该把包塞进哪个 socket 的队列。</span></p><p><span class="marginnote">可以把它想象成快递分拣：以太网头是外箱、IP 头是面单、TCP 头是收件人房间号。每过一层撕掉一层包装，最后只有房间号留下来决定敲门找谁。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>netif_receive_skb</code> → ingress qdisc（可选）→ <code>ip_rcv</code> → netfilter → <code>ip_local_deliver</code> → L4。TCP：状态机、缓冲、ACK。对照存储 RX：没有「文件偏移」，只有端口与地址。对照 <a href="/cs/device-nodes">设备节点</a>：<code>/dev/net/tun</code> 会在这条路径中途插入。</p>',10)),(r(),E(l,null,{default:s(()=>[d(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20NAPI%5B%22NAPI%20poll%22%5D%20--%3E%20GRO%5B%22GRO%22%5D%0A%20%20GRO%20--%3E%20ETH%5B%22eth_type_trans%22%5D%0A%20%20ETH%20--%3E%20IP%5B%22ip_rcv%22%5D%0A%20%20IP%20--%3E%20L4%5B%22tcp%2Fudp_rcv%22%5D%0A%20%20L4%20--%3E%20Q%5B%22sk%20%E6%8E%A5%E6%94%B6%E9%98%9F%E5%88%97%22%5D%0A%20%20Q%20--%3E%20WAKE%5B%22%E5%94%A4%E9%86%92%E8%BF%9B%E7%A8%8B%22%5D%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[t(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=a("h2",{id:"机制",tabindex:"-1"},[t("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=a("p",null,"RX 路径是「把 DMA 来的字节变成进程可读缓冲」的编译结果：每层剥头，最后是 socket buffer。性能问题几乎都是：几次缓存未命中、几次锁、是否跨 NUMA。不要写成七层 OSI 教材重开——对象是 Linux 函数链。",-1)),e[5]||(e[5]=a("p",null,[a("span",{class:"marginnote"},[t("数字实例：假设接收队列上限 1000 个 skb，"),a("code",null,"sk_data_ready"),t(" 唤醒的进程正被调度器压住 5 毫秒没跑；10 Gbps 链路每毫秒约 800 个 1500 字节的包涌向同一个 socket——5 毫秒就是约 4000 个包，队列只装得下 1000，其余全在这里丢。丢包不总在网卡，也可能在协议栈最末端。")])],-1)),(r(),E(l,null,{default:s(()=>[d(o,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20L4%5B%22tcp_v4_rcv%20%E6%8B%BF%E5%88%B0%E6%AE%B5%22%5D%20--%3E%20LOOK%7B%22%E5%9B%9B%E5%85%83%E7%BB%84%E6%9F%A5%E5%88%B0%20sock%3F%22%7D%0A%20%20LOOK%20--%20%22%E6%9C%AA%E5%91%BD%E4%B8%AD%22%20--%3E%20STATE%7B%22%E6%9C%AC%E6%9C%BA%E6%9C%89%E6%97%A0%E7%9B%91%E5%90%AC%3F%22%7D%0A%20%20STATE%20--%20%22%E6%97%A0%22%20--%3E%20DROP%5B%22%E4%B8%A2%E5%BC%83%E6%88%96%E5%9B%9E%20RST%22%5D%0A%20%20STATE%20--%20%22%E6%9C%89%22%20--%3E%20SYN%5B%22%E6%8C%89%E6%8F%A1%E6%89%8B%E7%8A%B6%E6%80%81%E5%A4%84%E7%90%86%20SYN%22%5D%0A%20%20LOOK%20--%20%22%E5%91%BD%E4%B8%AD%22%20--%3E%20Q%7B%22%E6%8E%A5%E6%94%B6%E9%98%9F%E5%88%97%E6%9C%AA%E6%BB%A1%3F%22%7D%0A%20%20Q%20--%20%22%E6%9C%AA%E6%BB%A1%22%20--%3E%20ENQ%5B%22skb%20%E6%8C%82%E5%85%A5%20sk%20%E9%98%9F%E5%88%97%22%5D%0A%20%20ENQ%20--%3E%20RDY%5B%22sk_data_ready%20%E5%94%A4%E9%86%92%22%5D%0A%20%20Q%20--%20%22%E5%B7%B2%E6%BB%A1%22%20--%3E%20LOSE%5B%22%E4%B8%A2%E6%AE%B5%2C%20%E5%90%8E%E9%9D%A0%E9%87%8D%E4%BC%A0%E6%81%A2%E5%A4%8D%22%5D%0A"})]),fallback:s(()=>[...e[1]||(e[1]=[t(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=i('<p>这张图回答的问题是：包走到 L4 之后，除了「进队列、唤醒」这条正路，还有哪几个出口会把它扔掉——查找未命中、队列已满、无监听，三条丢弃路径都在这里分岔。</p><p>与 <a href="/cs/nfs-semantics">NFS</a>：NFS 只是这路径上的一种 L4 负载。</p><p>实现上：early demux 用缓存的 sock 跳过一次查找。socket filter 与 tc ingress 可在协议层前丢包。无套接字的 TCP 段走 RST 或静默丢，取决于状态。 读法上只引用<a href="/cs/gro-gso">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「网络栈 / 收发路径」课序里，对象是 <strong>接收路径</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 IPv6 扩展头的全部处理。不保证转发路径（不是本机交付）的每一跳设备。下一课对侧：从 <code>sendmsg</code> 到网卡的 TX 与 qdisc。</p><p>版本字段会变，课序钉的是机制对象「接收路径」，不是某一主线内核的结构体名。 后课默认：包经协议栈进入 sk 队列。发送如何排队整形，下一课 TX/qdisc。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RX：NAPI → 协议分发 → 套接字队列 → 唤醒。</li><li>netfilter 与 RPS 插在这条链上。</li><li>发送路径与 qdisc 是下一课。</li><li>出处：Benvenuti <em>ULNI</em>；Linux net/core；Stevens。</li></ul>',10))])}const k=n(A,[["render",B]]);export{h as __pageData,k as default};
